scripts.preRequest:
// Dynamic values are generated fresh on every send.
frap.request.setHeader('X-Request-Id', crypto.randomUUID())
frap.request.setHeader('X-Sent-At', new Date().toISOString())

scripts.postResponse:
frap.test('our header made it through', () => {
  const headers = frap.response.json().headers
  frap.expect(headers['X-Request-Id']).toBeDefined()
})
